// Palette drift: a calm bed of full-strength colour whose hues travel slowly, varying with depth, height and
// a soft fbm swirl. A good bottom layer to stack sweeps, sparkles or chases on.
const params = {
  hue: { value: 0.6, min: 0, max: 1, step: 0.01, label: 'Starting hue' },
  drift: { value: 0.02, min: 0, max: 0.2, step: 0.005, label: 'Hue turns per second' },
  spread: { value: 0.25, min: 0, max: 1, step: 0.01, label: 'Hue spread across the layer' },
  swirl: { value: 0.12, min: 0, max: 0.5, step: 0.01 },
  saturation: { value: 1, min: 0.5, max: 1, step: 0.01 },
};

function pixel(p, t, P) {
  const h = P.hue + t * P.drift
          + P.spread * (0.6 * p.lx + 0.4 * p.ly)
          + P.swirl * (fbm(p.lx * 2, p.ly * 2, p.lz * 2 + t * 0.05) - 0.5);
  return hsv(h, P.saturation, 1);
}

// Rose chase: petals light in turn round the rose window (petal 0-15 clockwise, row 1-7 outward) while rings
// breathe outward; elsewhere a and r round the layer's centre stand in, so it turns over the whole façade.
const params = {
  speed: { value: 0.25, min: -2, max: 2, step: 0.01, label: 'Turns per second (− anticlockwise)' },
  hands: { value: 2, min: 1, max: 8, step: 1 },
  trail: { value: 3, min: 0.5, max: 12, step: 0.1, label: 'Trail (petals)' },
  breathe: { value: 0.4, min: 0, max: 2, step: 0.01, label: 'Rings per second' },
  base: { value: '#1b0080', type: 'color' },
  chase: { value: '#ff00a0', type: 'color' },
  ring: { value: '#ffb000', type: 'color' },
};

function pixel(p, t, P) {
  const petal = p.petal >= 0 ? p.petal : floor(p.a * 16);
  const ring = p.row > 0 ? p.row : 1 + floor(p.r * 6.999);
  // Petals since a hand passed, 0 right behind it.
  const dir = P.speed < 0 ? -1 : 1;
  const since = fract(dir * (t * P.speed - petal / 16) * P.hands) * 16 / P.hands;
  const lit = exp(-since / P.trail);
  const swell = pulse((ring - 1) / 7 - t * P.breathe, 0.12);
  return mix(mix(P.base, P.chase, lit), P.ring, swell * 0.85);
}

// Arch chase: arches light in turn by strand number (mod count: 5 goes bay by bay, front to back), each
// filling along its wire behind a highlight head (plus energy), then fading over `trail` steps. rate.
const params = {
  rate: { value: 1, min: 0.25, max: 6, step: 0.05, label: 'Arches a second' },
  count: { value: 5, min: 2, max: 40, step: 1, label: 'Arches in the cycle' },
  trail: { value: 1.5, min: 0.2, max: 6, step: 0.1, label: 'Fade (steps)' },
};

function pixel(p, t, P, G) {
  const n = round(P.count), x = t * P.rate, step = floor(x), f = x - step;
  const age = (((step - p.strand) % n) + n) % n + f;           // steps since this arch's turn began
  const head = f * 1.3;
  const lit = age < 1 ? smoothstep(head, head - 0.05, p.u) : exp(-(age - 1) / P.trail);
  const c = mix(pal('low', p.u), pal('body', p.u), lit);
  return age < 1 ? mix(c, pal('high'), exp(-((p.u - head) ** 2) * 600) * (0.5 + 0.5 * G.energy)) : c;
}

// Canopy rain: highlight drops with accent tails streak down the layer in columns across width and depth
// (energy turns a shower into a downpour), beading on the canopy runs, where they linger, over the low colour at
// `sky`. columns, speed, tail.
const params = {
  columns: { value: 30, min: 8, max: 80, step: 1, label: 'Columns across' },
  speed: { value: 0.9, min: 0.2, max: 3, step: 0.05, label: 'Layer heights a second' },
  tail: { value: 0.12, min: 0.02, max: 0.4, step: 0.01, label: 'Tail length' },
  sky: { value: 0.5, min: 0, max: 1, step: 0.01, label: 'Sky brightness' },
};

function pixel(p, t, P, G) {
  const col = floor(p.lz * P.columns) * 7 + floor(p.lx * 6.999), long = p.zone === 'canopy' ? 4 : 1;
  let v = 0;
  for (let m = 0; m < 2; m++) {
    if (rand(col, m, 5) > 0.3 + 0.7 * G.energy) continue;
    const head = 1.1 - fract(t * P.speed * (0.8 + 0.4 * rand(col, m, 1)) / 1.4 + rand(col, m, 2)) * 1.4;
    const above = p.ly - head;                                   // ≥ 0 above the head, where its tail is
    if (above > -0.01) v = max(v, exp(-max(0, above) / (P.tail * long)));
  }
  const c = mix(scale(pal('low', p.ly), P.sky), pal('accent', p.ly), min(1, v * 1.2));
  return mix(c, pal('high'), smoothstep(0.8, 1, v));
}

// Rose bloom: the rose window opens ring by ring (row 1–7; elsewhere r) from its heart, holds, closes to a
// bud. cycle (seconds), petals (every other leans to accent), flare (highlight as a ring opens, plus energy).
const params = {
  cycle: { value: 6, min: 2, max: 30, step: 0.5, label: 'Seconds per bloom' },
  petals: { value: 0.4, min: 0, max: 1, step: 0.01, label: 'Petal contrast' },
  flare: { value: 0.7, min: 0, max: 1, step: 0.01, label: 'Highlight as a ring opens' },
};

function pixel(p, t, P, G) {
  const rr = p.row > 0 ? (p.row - 0.5) / 7 : p.r, petal = p.petal >= 0 ? p.petal : floor(p.a * 16);
  const ph = fract(t / P.cycle);
  const front = (smoothstep(0, 0.55, ph) - smoothstep(0.75, 1, ph)) * 1.1;
  const open = smoothstep(front, front - 0.08, rr);
  const bloom = mix(pal('body', rr), pal('accent', rr), (petal % 2) * P.petals);
  const c = mix(pal('low', rr), bloom, open);
  const fl = ph < 0.6 ? exp(-(((rr - front) / 0.07) ** 2)) * P.flare * (0.5 + 0.5 * G.energy) : 0;
  return mix(c, pal('high'), fl);
}

// Spire rise: body colour climbs every spire (ly) under a highlight head (plus energy), crowns the tip, lifts
// away; towers (zones) start `stagger` of a rise apart. every (seconds a rise), head (its length).
const params = {
  every: { value: 4, min: 1, max: 20, step: 0.1, label: 'Seconds per rise' },
  stagger: { value: 0.15, min: 0, max: 1, step: 0.01, label: 'Towers apart (share of a rise)' },
  head: { value: 0.06, min: 0.02, max: 0.3, step: 0.01, label: 'Head length' },
};

function pixel(p, t, P, G) {
  const ph = fract(t / P.every - rand(p.zi, 3) * P.stagger);
  const top = smoothstep(0, 0.6, ph) * 1.1, foot = smoothstep(0.72, 1, ph) * 1.1;   // the lit column's ends
  const lit = smoothstep(top, top - 0.03, p.ly) * smoothstep(foot - 0.03, foot, p.ly);
  const c = mix(pal('low', p.ly), pal('body', p.ly), lit);
  const head = exp(-(((p.ly - top) / P.head) ** 2)) * (1 - foot);
  const crown = pulse(ph - 0.66, 0.1) * smoothstep(0.7, 1, p.ly);
  return mix(c, pal('high'), max(head * (0.5 + 0.5 * G.energy), crown));
}

// Meteors: shooting stars race along every strand (u, i, n place each LED on its wire), trailing fading tails.
// Each strand has its own seeded start, pace and direction (rand(p.strand, …)), and a gap between laps.
const params = {
  speed: { value: 60, min: 5, max: 200, step: 1, label: 'LEDs per second' },
  count: { value: 2, min: 1, max: 4, step: 1, label: 'Meteors per strand' },
  tail: { value: 10, min: 2, max: 60, step: 1, label: 'Tail length (LEDs)' },
  gap: { value: 80, min: 0, max: 300, step: 1, label: 'Gap between laps (LEDs)' },
  both: { value: true, type: 'toggle', label: 'Both directions' },
  sky: { value: '#0a0a5c', type: 'color' },
  color: { value: '#00c8ff', type: 'color' },
  head: { value: '#ffffff', type: 'color' },
};

function pixel(p, t, P) {
  const s = p.strand;
  const reverse = P.both && rand(s, 7) < 0.5;
  const i = reverse ? p.n - 1 - p.i : p.i;               // LEDs from this run's start
  const lap = p.n + P.gap;
  let v = 0;
  for (let m = 0; m < P.count; m++) {
    const pace = P.speed * (0.7 + 0.6 * rand(s, m, 3));
    const headAt = fract(rand(s, m) + t * pace / lap) * lap;
    const behind = headAt - i;                            // LEDs behind the head
    if (behind >= 0) v = max(v, exp(-behind / P.tail));
  }
  const c = mix(P.color, P.head, smoothstep(0.75, 1, v));
  return mix(P.sky, c, v);
}

// Probe: every pixel field the pattern API gives, folded into a colour.
function pixel(p, t, P) {
  const a = (p.k % 97) / 97 + p.zi / 31 + p.strand / 101 + p.row / 7 + (p.petal + 1) / 16;
  const b = p.u + p.i / 300 + p.n / 250 + p.a + p.r + p.seed;
  const c = p.lx + p.ly * 2 + p.lz * 3 + p.x + p.y + p.z + (p.X + p.Y + p.Z) / 40 + (p.zone.length % 7) / 7;
  return [fract(a + t), fract(b + t * 0.5), fract(c - t)];
}

