// Clouds: soft billows of fbm noise drift across the layer, from deep sky to bright cloud; `cover` sets how
// much sky they hide and G.energy thickens them. Mark it "input only" to mask another source with it.
const params = {
  scale: { value: 2.5, min: 0.5, max: 8, step: 0.1, label: 'Billow size (smaller is bigger)' },
  drift: { value: 0.15, min: 0, max: 1, step: 0.01, label: 'Drift speed' },
  cover: { value: 0.5, min: 0, max: 1, step: 0.01, label: 'Cloud cover' },
  sky: { value: '#0b1a4a', type: 'color' },
  cloud: { value: '#e8ecff', type: 'color' },
};

function pixel(p, t, P, G) {
  const s = t * P.drift;
  const n = fbm(p.lz * P.scale + s, p.ly * P.scale * 0.6 - s * 0.2, p.lx * P.scale * 0.5 + s * 0.3);
  const edge = 1 - clamp(P.cover + (G.energy - 0.5) * 0.3);
  const v = smoothstep(edge - 0.15, edge + 0.15, n);
  return mix(P.sky, P.cloud, v);
}

// Mask: shows the chain only where its input (another source here, usually "input only") is bright: past
// `cutoff` it shows, below it the alpha falls toward 1 − amount; invert masks where it is dark. No input: no-op.
const params = {
  amount: { value: 1, min: 0, max: 1, step: 0.01, label: 'Mask strength' },
  cutoff: { value: 0.35, min: 0, max: 1, step: 0.01, label: 'Brightness where it opens' },
  softness: { value: 0.3, min: 0.01, max: 1, step: 0.01, label: 'Edge softness' },
  invert: { value: false, type: 'toggle', label: 'Show where the input is dark' },
};

function filter(c, q, t, P, G, x) {
  if (!x) return c;
  const b = max(x[0], x[1], x[2]) * x[3];
  let m = smoothstep(P.cutoff - P.softness / 2, P.cutoff + P.softness / 2, b);
  if (P.invert) m = 1 - m;
  c[3] *= 1 - P.amount * (1 - m);        // c is the chain's colour: change it and hand it back
  return c;
}

// Mirror: folds the layer onto itself before the modules after it draw: left-right (lz, z, a), front-back
// (lx, x), up-down (ly, y), or every wire at its middle (u, i), so chases run in from both ends.
const params = {
  leftRight: { value: true, type: 'toggle', label: 'Left ↔ right' },
  frontBack: { value: false, type: 'toggle', label: 'Front ↔ back' },
  upDown: { value: false, type: 'toggle', label: 'Up ↔ down' },
  along: { value: false, type: 'toggle', label: 'Along strands' },
};

const fold = (v) => (v > 0.5 ? 1 - v : v);

function warp(q, t, P) {
  if (P.leftRight) { q.lz = fold(q.lz); q.z = fold(q.z); q.a = fold(q.a); }
  if (P.frontBack) { q.lx = fold(q.lx); q.x = fold(q.x); }
  if (P.upDown) { q.ly = fold(q.ly); q.y = fold(q.y); }
  if (P.along) { q.u = fold(q.u); q.i = min(q.i, q.n - 1 - q.i); }
}

// Starfield: every LED a star with its own rhythm (rate, phase and colour from its seed), glinting briefly
// (pulse) over a sky that drifts between two deep blues on slow noise, so the dark is never flat.
const params = {
  rate: { value: 0.35, min: 0.05, max: 3, step: 0.01, label: 'Glints per second' },
  density: { value: 0.5, min: 0, max: 1, step: 0.01, label: 'Share of LEDs that are stars' },
  sharp: { value: 0.12, min: 0.02, max: 0.5, step: 0.01, label: 'Glint length' },
  sky: { value: '#08084a', type: 'color' },
  sky2: { value: '#1c0060', type: 'color' },
  star: { value: '#d8f0ff', type: 'color' },
  warm: { value: '#ffd27a', type: 'color' },
};

function pixel(p, t, P) {
  const bed = mix(P.sky, P.sky2, noise(p.lx * 3, p.ly * 3 + t * 0.05, p.lz * 3));
  if (rand(p.k, 1) > P.density) return bed;
  const rate = P.rate * (0.5 + rand(p.k, 2));
  const glint = pulse(p.seed * 13.7 + t * rate, P.sharp);
  return mix(bed, mix(P.star, P.warm, rand(p.k, 3)), glint);
}

// Tint: recolours the chain from one role of the look's palette, keeping its light and shade: brightness walks
// along the role (pal(role, t)), so the look follows whichever palette is picked. amount blends.
const params = {
  role: { value: 1, min: 0, max: 3, step: 1, label: 'Role: low, body, accent, high' },
  amount: { value: 1, min: 0, max: 1, step: 0.01 },
  spread: { value: 1, min: 0, max: 1, step: 0.01, label: 'How far brightness walks the role' },
};
const ROLES = ['low', 'body', 'accent', 'high'];

function filter(c, q, t, P) {
  const v = max(c[0], c[1], c[2]);
  const tint = pal(ROLES[clamp(round(P.role), 0, 3)], v * P.spread);
  for (let i = 0; i < 3; i++) c[i] = mix(c[i], tint[i] * v, P.amount);
  return c;
}

// Rotate: turns lz and ly about the layer's centre (and the angle a with them) by `angle` turns, plus `spin`
// turns a second, so anything drawn across the layer or round it rotates.
const params = {
  angle: { value: 0.125, min: -0.5, max: 0.5, step: 0.005, label: 'Angle (turns)' },
  spin: { value: 0, min: -1, max: 1, step: 0.01, label: 'Turns a second' },
};

function warp(q, t, P) {
  const turn = P.angle + t * P.spin;
  const s = sin(TAU * turn), c = cos(TAU * turn);
  const dz = q.lz - 0.5, dy = q.ly - 0.5;
  q.lz = 0.5 + dz * c - dy * s;
  q.ly = 0.5 + dz * s + dy * c;
  q.a = fract(q.a + turn);
}

// Rose chase: petals light in turn round the rose window (petal 0-15 clockwise, row 1-7 outward) while rings
// breathe outward; elsewhere a and r round the layer's centre stand in, so it turns over the whole façade.
const params = {
  speed: { value: 0.25, min: -2, max: 2, step: 0.01, label: 'Turns per second (− anticlockwise)' },
  hands: { value: 2, min: 1, max: 8, step: 1 },
  trail: { value: 3, min: 0.5, max: 12, step: 0.1, label: 'Trail (petals)' },
  breathe: { value: 0.4, min: 0, max: 2, step: 0.01, label: 'Rings per second' },
  base: { value: '#1b0080', type: 'color' },
  chase: { value: '#ff00a0', type: 'color' },
  ring: { value: '#ffb000', type: 'color' },
};

function pixel(p, t, P) {
  const petal = p.petal >= 0 ? p.petal : floor(p.a * 16);
  const ring = p.row > 0 ? p.row : 1 + floor(p.r * 6.999);
  // Petals since a hand passed, 0 right behind it.
  const dir = P.speed < 0 ? -1 : 1;
  const since = fract(dir * (t * P.speed - petal / 16) * P.hands) * 16 / P.hands;
  const lit = exp(-since / P.trail);
  const swell = pulse((ring - 1) / 7 - t * P.breathe, 0.12);
  return mix(mix(P.base, P.chase, lit), P.ring, swell * 0.85);
}

// Hue shift: turns colours round the wheel (round the grey axis, so brightness holds) by place along an axis:
// across, up, front to back, round (a) or along strands (u). spread (turns over it), speed (turns a second).
const params = {
  spread: { value: 0.5, min: -2, max: 2, step: 0.01, label: 'Turns of hue across the axis' },
  axis: { value: 0, min: 0, max: 4, step: 1, label: 'Across, up, front → back, round, along' },
  speed: { value: 0.05, min: -1, max: 1, step: 0.01, label: 'Turns a second' },
};

function filter(c, q, t, P) {
  const a = round(P.axis), x = a === 0 ? q.lz : a === 1 ? q.ly : a === 2 ? q.lx : a === 3 ? q.a : q.u;
  const turn = TAU * (x * P.spread + t * P.speed), cs = cos(turn), s = sin(turn) / sqrt(3), k = (1 - cs) / 3;
  const r = c[0], g = c[1], b = c[2];
  c[0] = clamp(r * (cs + k) + g * (k - s) + b * (k + s));
  c[1] = clamp(r * (k + s) + g * (cs + k) + b * (k - s));
  c[2] = clamp(r * (k - s) + g * (k + s) + b * (cs + k));
  return c;
}
